// Evolution sends every subscribed event here. Keep only real inbound
// text messages from individual chats. Dropping fromMe is what stops the
// bot replying to its own messages forever.
//
// SECURITY: the webhook path itself is the shared secret — only Evolution
// knows the full URL. See the red Security note on the canvas.

const out = [];

for (const item of $input.all()) {
  const body = item.json.body ?? item.json;

  if (body.event && body.event !== 'messages.upsert') continue;

  const data = body.data ?? {};
  const key = data.key ?? {};
  if (key.fromMe) continue;

  const jid = key.remoteJid || '';
  if (!jid.endsWith('@s.whatsapp.net')) continue;

  const msg = data.message ?? {};
  const text = (
    msg.conversation ??
    msg.extendedTextMessage?.text ??
    msg.imageMessage?.caption ??
    ''
  ).trim();
  if (!text) continue;

  out.push({
    json: {
      chatId: jid,
      phone: jid.split('@')[0],
      name: data.pushName || '',
      text,
      instance: body.instance || 'whatsapp'
    }
  });
}

return out;
